    fullName: { ar: 'بكر بن عبد الله أبو زيد بن محمد بن عبد الله بن بكر بن عثمان', az: 'Bəkr ibn Abdullah Əbu Zeyd ibn Məhəmməd ibn Abdullah ibn Bəkr ibn Osman', en: 'Bakr ibn Abd Allah Abu Zayd ibn Muhammad ibn Abd Allah ibn Bakr ibn Uthman', ru: 'Бакр ибн Абдуллах Абу Зейд ибн Мухаммад ибн Абдуллах ибн Бакр ибн Усман', tr: 'Bekir b. Abdullah Ebû Zeyd b. Muhammed b. Abdullah b. Bekir b. Osman' },
    title: { ar: 'الفقيه، عضو هيئة كبار العلماء', az: 'Fəqih, Böyük Alimlər Şurasının üzvü', en: 'Jurist, member of the Council of Senior Scholars', ru: 'Факих, член Совета старших учёных', tr: 'Fakih, Büyük Âlimler Heyeti üyesi' },
